'use strict';
const grid=document.querySelector('#projects'),dialog=document.querySelector('#project-dialog'),player=document.querySelector('#project-player');
let projects=[],filter='All',limit=6,lastTrigger;
const safe=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){grid.classList.toggle('short-form-grid',filter==='Short form');grid.classList.toggle('long-form-grid',filter==='Long form');grid.classList.toggle('wedding-grid',filter==='Wedding films');const visible=projects.filter(p=>filter==='All'||p.category===filter);grid.innerHTML=visible.slice(0,limit).map(p=>`<article class="project-card"><button data-project="${projects.indexOf(p)}" aria-label="Watch ${safe(p.title)}"><div class="project-image"><img src="assets/${p.cover}.jpg" width="1200" height="900" loading="lazy" alt="Frame from ${safe(p.title)}"><span class="project-play" aria-hidden="true">▶</span></div><div class="project-info"><div><h3>${safe(p.title)}</h3><p>${safe(p.category)} · ${p.files.length} ${p.files.length===1?'film':'films'}</p></div><span aria-hidden="true">↗</span></div></button></article>`).join('');document.querySelector('#work-status').textContent=`${Math.min(limit,visible.length)} of ${visible.length} projects`;document.querySelector('#load-more').hidden=limit>=visible.length;}
function selectFilm(project,index){const file=project.files[index];player.src=`https://drive.google.com/file/d/${file.id}/preview`;player.title=`${project.title} — ${file.title}`;document.querySelector('#drive-original').href=`https://drive.google.com/file/d/${file.id}/view`;document.querySelectorAll('.playlist button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));}
function openProject(index,trigger){const project=projects[index];if(!project)return;lastTrigger=trigger;document.querySelector('#dialog-title').textContent=project.title;document.querySelector('#dialog-category').textContent=project.category.toUpperCase();const list=document.querySelector('#playlist');list.innerHTML=project.files.map((f,i)=>`<button data-film="${i}" aria-pressed="${i===0}">${String(i+1).padStart(2,'0')} — ${safe(f.title)}</button>`).join('');list.onclick=e=>{const b=e.target.closest('[data-film]');if(b)selectFilm(project,Number(b.dataset.film));};selectFilm(project,0);dialog.showModal();document.body.classList.add('modal-open');}
grid.addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(b)openProject(Number(b.dataset.project),b);});
document.querySelectorAll('.project-link').forEach(b=>b.addEventListener('click',()=>openProject(projects.findIndex(p=>p.title===b.dataset.title),b)));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;limit=6;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();}));
document.querySelector('#load-more').addEventListener('click',()=>{const old=limit;limit+=6;render();grid.querySelectorAll('button')[old]?.focus({preventScroll:true});});
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{player.removeAttribute('src');document.body.classList.remove('modal-open');lastTrigger?.focus({preventScroll:true});});
const toggle=document.querySelector('#menu-toggle'),navigation=document.querySelector('#navigation');
function closeMenu(){navigation.hidden=true;document.body.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false');toggle.focus({preventScroll:true});}
toggle.addEventListener('click',()=>{navigation.hidden=false;document.body.classList.add('menu-open');toggle.setAttribute('aria-expanded','true');navigation.querySelector('button').focus();});
document.querySelector('#menu-close').addEventListener('click',closeMenu);
navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(!navigation.hidden){if(e.key==='Escape')closeMenu();if(e.key==='Tab'){const items=[...navigation.querySelectorAll('a,button')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
const observer=new IntersectionObserver(([entry])=>document.body.classList.toggle('at-cover',entry.isIntersecting),{threshold:.5});observer.observe(document.querySelector('#home'));
document.querySelector('#copy-email').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('Sharathchandra0122@gmail.com');status.textContent='Email copied.';}catch{status.textContent='Sharathchandra0122@gmail.com';}});
fetch('projects.json').then(r=>{if(!r.ok)throw Error('Unavailable');return r.json();}).then(data=>{projects=data;document.querySelector('#archive-count').textContent=`${data.length} projects · ${data.reduce((n,p)=>n+p.files.length,0)} films`;render();}).catch(()=>{grid.innerHTML='<p>View the <a href="https://drive.google.com/drive/folders/1mRFZlkO5Euvz-O2XW0Yg2n1jTw8EczcL">complete work archive ↗</a>.</p>';document.querySelector('#load-more').hidden=true;document.querySelectorAll('.project-link').forEach(b=>{b.disabled=true;});});
